<?php

function getMaxOccurrence(array $numbers): ?int
{
    if (empty($numbers)) {
        return null;
    }

    $counts = array_count_values($numbers);

    $maxCount = -1;
    $result = null;

    foreach ($counts as $number => $count) {
        if ($count > $maxCount) {
            $maxCount = $count;
            $result = $number;
        } elseif ($count === $maxCount) {
            if ($result === null || $number < $result) {
                $result = $number;
            }
        }
    }

    return $result;
}
